#include <string>
#include <algorithm>

class Solution {
public:
    bool checkIfCanBreak(std::string s1, std::string s2) {
        std::sort(s1.begin(), s1.end());
        std::sort(s2.begin(), s2.end());
        bool canBreak1 = true, canBreak2 = true;
        for (int i = 0; i < (int)s1.size(); ++i) {
            if (s1[i] < s2[i]) canBreak1 = false;
            if (s2[i] < s1[i]) canBreak2 = false;
        }
        return canBreak1 || canBreak2;
    }
};

import java.util.*;

class Solution {
    public boolean checkIfCanBreak(String s1, String s2) {
        char[] a = s1.toCharArray();
        char[] b = s2.toCharArray();
        Arrays.sort(a);
        Arrays.sort(b);
        boolean canBreak1 = true, canBreak2 = true;
        for (int i = 0; i < a.length; i++) {
            if (a[i] < b[i]) canBreak1 = false;
            if (b[i] < a[i]) canBreak2 = false;
        }
        return canBreak1 || canBreak2;
    }
}

